const defaultState={
  todos:[],
  subjects:[],
  sessions:[],
  exams:[],
  flashcards:[],
  timetable:[],
  sport:{
    workouts:[],
    programs:[],
    body:[],
    photos:{before:null, after:null}
  },
  code:{
    projects:[],
    snippets:[],
  },
  notes:{folders:[], items:[]},
  gamification:{xp:0, level:1, streak:0, badges:[]},
  profile:{name:'', role:'', goal:''},
  settings:{accent:'#8b5cf6', bg:'dark', blur:18, density:'comfortable', sound:true, confetti:true, onboardingDone:false, language:'fa'},
  focusEditor:'function hello(){\n  console.log(\"سلام دنیا\");\n}',
};
function tr(value){ const text=String(value??''); return state?.settings?.language==='en'?(uiTranslations[text]||text):text; }
function load(){ try{ const r=localStorage.getItem('dastyar_full_soft'); if(r){ const p=JSON.parse(r); return {...structuredClone(defaultState), ...p, sport:{...defaultState.sport, ...(p.sport||{}), photos:{...defaultState.sport.photos, ...(p.sport?.photos||{})}}, code:{...defaultState.code, ...(p.code||{})}, settings:{...defaultState.settings, ...(p.settings||{})}, profile:{...defaultState.profile, ...(p.profile||{})}, gamification:{...defaultState.gamification, ...(p.gamification||{})}} } }catch{} return structuredClone(defaultState); }
let state=load(); let saveWarned=false;
function save(){ try{ localStorage.setItem('dastyar_full_soft', JSON.stringify(state)); }catch(e){ if(!saveWarned){ saveWarned=true; alert('ذخیره‌سازی ناموفق بود؛ حافظه‌ی مرورگر پر است یا غیرفعال است. از بخش شخصی‌سازی از داده‌ها خروجی بگیرید.'); } } }
function esc(v){ return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function shrinkImage(file,max=900){ return new Promise((res,rej)=>{ const r=new FileReader(); r.onerror=rej; r.onload=()=>{ const img=new Image(); img.onerror=rej; img.onload=()=>{ const k=Math.min(1,max/Math.max(img.width,img.height)); const c=document.createElement('canvas'); c.width=Math.round(img.width*k); c.height=Math.round(img.height*k); c.getContext('2d').drawImage(img,0,0,c.width,c.height); res(c.toDataURL('image/jpeg',.8)); }; img.src=r.result; }; r.readAsDataURL(file); }); }
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)]; const uid=()=>Math.random().toString(36).slice(2,7);
function fmtJalali(d=new Date()){ const en=state.settings.language==='en'; try{return new Intl.DateTimeFormat(en?'en-US':'fa-IR-u-ca-persian',{year:'numeric',month:'short',day:'numeric'}).format(d)}catch{return d.toLocaleDateString(en?'en-US':'fa-IR')} }
function fmtTime(d=new Date()){ return d.toLocaleTimeString(state.settings.language==='en'?'en-US':'fa-IR',{hour:'2-digit',minute:'2-digit',hour12:false}); }
function relDays(ds){ if(!ds) return state.settings.language==='en'?'No due date':'بدون موعد'; const diff=Math.ceil((new Date(ds)-new Date())/86400000); if(diff===0)return tr('امروز'); if(diff===1)return tr('فردا'); if(diff<0)return state.settings.language==='en'?`${Math.abs(diff)} days ago`:`${Math.abs(diff)} روز پیش`; return state.settings.language==='en'?`${diff} days from now`:`${diff} روز دیگر`; }
const themes={dark:{name:'تاریک شیشه‌ای', bg:'radial-gradient(900px 500px at 88% -8%, rgba(139,92,246,.32), transparent 60%), radial-gradient(700px 400px at -10% 18%, rgba(6,182,214,.22), transparent 62%), #08080a', preview:'#08080a'}, midnight:{name:'نیمه‌شب', bg:'radial-gradient(800px 400px at 50% -20%, rgba(30,58,138,.28), transparent), #0a0a0f', preview:'#0a0a0f'}, aurora:{name:'شفق نرم', bg:'radial-gradient(700px 400px at 10% 10%, rgba(34,197,94,.20), transparent), #08080a', preview:'#0a1a12'}};
const accents=['#8b5cf6','#06b6d4','#ec4899','#22c55e','#f59e0b'];
let audioCtx=null; function ensureAudio(){ if(!audioCtx) audioCtx=new (window.AudioContext||window.webkitAudioContext)(); }
function playPop(f=700){ if(!state.settings.sound) return; try{ ensureAudio(); const o=audioCtx.createOscillator(); const g=audioCtx.createGain(); o.type='sine'; o.frequency.setValueAtTime(f, audioCtx.currentTime); o.frequency.exponentialRampToValueAtTime(f*1.3, audioCtx.currentTime+0.07); g.gain.setValueAtTime(0.14, audioCtx.currentTime); g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime+0.16); o.connect(g); g.connect(audioCtx.destination); o.start(); o.stop(audioCtx.currentTime+0.16);}catch{} }
function playSuccess(){ playPop(600); setTimeout(()=>playPop(900), 70); setTimeout(()=>playPop(1200), 140); }
function haptic(ms=18){ if(!state.settings.sound) return; if('vibrate' in navigator) navigator.vibrate(ms); }
function launchConfetti(){
  if(!state.settings.confetti) return;
  const canvas=$('#confettiCanvas'); const ctx=canvas.getContext('2d'); canvas.width=innerWidth; canvas.height=innerHeight; canvas.style.display='block';
  const pieces=[...Array(90)].map(()=>({x:Math.random()*canvas.width, y:Math.random()*-canvas.height, r:Math.random()*6+3, c:`hsl(${Math.random()*60+250},100%,65%)`, vx:(Math.random()-0.5)*6, vy:Math.random()*5+3, rot:Math.random()*360, vr:(Math.random()-0.5)*8}));
  let frame=0; (function loop(){ ctx.clearRect(0,0,canvas.width,canvas.height); pieces.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; p.vy+=0.10; p.rot+=p.vr; ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.rot*Math.PI/180); ctx.fillStyle=p.c; ctx.fillRect(-p.r/2,-p.r/2,p.r,p.r*0.6); ctx.restore(); }); frame++; if(frame<150) requestAnimationFrame(loop); else canvas.style.display='none'; })();
}
function applySettings(){
  const s=state.settings; document.documentElement.style.setProperty('--accent', s.accent); document.documentElement.style.setProperty('--blur', s.blur+'px'); document.documentElement.style.setProperty('--blur-strong', (s.blur+8)+'px');
  const bgEl=$('#bgEl'); const th=themes[s.bg]||themes.dark; bgEl.style.background=th.bg;
  document.body.className=document.body.className.replace(/density-\w+/g,'').trim(); document.body.classList.add('density-'+s.density);
  save();
}
applySettings();
function navigate(view){ playPop(500); haptic(12); $$('.nav-item').forEach(n=>n.classList.toggle('active', n.dataset.view===view)); $$('.view').forEach(v=>{ v.style.display=v.id===`view-${view}`?'block':'none'; if(v.id===`view-${view}`){ v.classList.remove('active'); void v.offsetWidth; v.classList.add('active'); } }); }
$$('.nav-item').forEach(n=>n.addEventListener('click',()=>navigate(n.dataset.view), {passive:true}));
function tick(){ if($('#clockBadge')) $('#clockBadge').textContent=fmtTime(new Date()); if($('#bigTime')) $('#bigTime').textContent=fmtTime(new Date()); if($('#gregDate')) $('#gregDate').textContent=fmtJalali(new Date()); if($('#jalaliDate')) $('#jalaliDate').textContent=fmtJalali(new Date()); }
setInterval(tick,1000); tick();
