// Dashboard drag soft
let dragSrc=null;
function initDashDrag(){
  const bento=$('#dashBento'); if(!bento) return;
  [...bento.querySelectorAll('.glass-card')].forEach(card=>{
    card.draggable=true;
    card.addEventListener('dragstart',e=>{ dragSrc=card; card.style.opacity='.5'; e.dataTransfer.effectAllowed='move'; }, {passive:true});
    card.addEventListener('dragend',()=>{ card.style.opacity='1'; $$('.glass-card', bento).forEach(c=>c.style.outline=''); }, {passive:true});
    card.addEventListener('dragover',e=>{ e.preventDefault(); card.style.outline='1px dashed var(--accent)'; }, {passive:false});
    card.addEventListener('dragleave',()=>{ card.style.outline=''; }, {passive:true});
    card.addEventListener('drop',e=>{ e.preventDefault(); card.style.outline=''; if(dragSrc && dragSrc!==card){ const parent=card.parentNode; const frag=document.createDocumentFragment(); if([...parent.children].indexOf(dragSrc) < [...parent.children].indexOf(card)) parent.insertBefore(dragSrc, card.nextSibling); else parent.insertBefore(dragSrc, card); playPop(700); haptic(18); } }, {passive:false});
  });
}
$('#shuffleDash')?.addEventListener('click',()=>{ const bento=$('#dashBento'); if(!bento) return; const cards=[...bento.children]; cards.sort(()=>Math.random()-0.5); cards.forEach(c=>bento.appendChild(c)); playPop(600); }, {passive:true});

// Gamification + growth tree + badges
function renderGamification(){
  const xp=state.gamification.xp||0; const level=Math.floor(Math.sqrt(xp/100))+1; const nextXp=Math.pow(level,2)*100; const prevXp=Math.pow(level-1,2)*100; const prog=((xp-prevXp)/(nextXp-prevXp)*100);
  if($('#studyLevel')) $('#studyLevel').textContent=level; if($('#studyLevelName')) $('#studyLevelName').textContent=['تازه‌کار','تلاشگر','حرفه‌ای','استاد'][Math.min(level-1,3)]; if($('#studyXPText')) $('#studyXPText').textContent=`${xp} / ${nextXp} XP`; if($('#studyXPBarDetailed')) $('#studyXPBarDetailed').style.width=prog+'%'; if($('#studyXPBar')) $('#studyXPBar').style.width=prog+'%'; if($('#globalStreak')) $('#globalStreak').textContent=state.gamification.streak||0; if($('#todayXP')) $('#todayXP').textContent=xp%100; if($('#dashLevel')) $('#dashLevel').textContent=level; if($('#globalXPBar')) $('#globalXPBar').style.width=prog+'%'; if($('#studyTodayBadge')) $('#studyTodayBadge').textContent=xp+' XP';
  const bg=$('#badgeGrid'); if(bg){ bg.innerHTML=''; const frag=document.createDocumentFragment(); state.gamification.badges.forEach(b=>{ const el=document.createElement('div'); el.className='badge-item'+(b.earned?' earned':''); el.textContent=b.icon; el.title=b.name; frag.appendChild(el); }); bg.appendChild(frag); }
  const dashBadges=$('#dashBadges'); if(dashBadges){ dashBadges.innerHTML=''; const frag=document.createDocumentFragment(); state.gamification.badges.slice(0,4).forEach(b=>{ const el=document.createElement('div'); el.className='badge-item'+(b.earned?' earned':''); el.textContent=b.icon; frag.appendChild(el); }); dashBadges.appendChild(frag); }
  const tree=$('#growthTree'); if(tree){ const lvl=level; let svg=`<g transform="translate(100,110)">`; svg+=`<rect x="-2.5" y="-40" width="5" height="40" rx="2.5" fill="#5a3a22"/>`; for(let i=0;i<Math.min(lvl*2,10);i++){ const ang=(i/10*100-50); const len=16+lvl*4; const x2=Math.sin(ang*Math.PI/180)*len; const y2=-Math.cos(ang*Math.PI/180)*len - (i%2)*6; svg+=`<line x1="0" y1="${-35+(i%3)*4}" x2="${x2}" y2="${y2}" stroke="#22c55e" stroke-width="${1.8+lvl*0.2}" stroke-linecap="round" opacity="${0.6+lvl*0.03}"/>`; if(Math.random()>0.25) svg+=`<circle cx="${x2}" cy="${y2}" r="${3+lvl*0.2}" fill="${['#22c55e','#86efac','#f59e0b'][i%3]}"/>`; } svg+=`</g>`; tree.innerHTML=svg; }
}

// Render dash
function renderDash(){
  const frag=document.createDocumentFragment(); const dashTodos=$('#dashTodos'); if(dashTodos){ dashTodos.innerHTML=''; state.todos.filter(t=>!t.done).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||({high:0,med:1,low:2}[a.prio]??1)-({high:0,med:1,low:2}[b.prio]??1)).slice(0,4).forEach(t=>{ const el=document.createElement('div'); el.className='item'; el.textContent=t.text; el.addEventListener('click',()=>{navigate('todos'); openTodoEdit(t.id)}, {passive:true}); frag.appendChild(el); }); dashTodos.appendChild(frag); }
  const total=state.todos.length, done=state.todos.filter(t=>t.done).length; const pct=total?Math.round(done/total*100):0;
  if($('#focusPct')) $('#focusPct').textContent=pct+'%'; if($('#focusBar')) $('#focusBar').style.width=pct+'%'; if($('#statDone')) $('#statDone').textContent=`${done}/${total}`; if($('#statTasks')) $('#statTasks').textContent=total;
  if($('#todoBadge')) $('#todoBadge').textContent=state.todos.filter(t=>!t.done).length;
  const today=new Date().toISOString().slice(0,10); const studyMinutes=state.sessions.filter(x=>String(x.date).slice(0,10)===today).reduce((sum,x)=>sum+(Number(x.duration)||0),0); if($('#studyBadge')) $('#studyBadge').textContent=state.settings.language==='en'?`${Math.floor(studyMinutes/60)}h`:`${Math.floor(studyMinutes/60)}س`; if($('#statStudy')) $('#statStudy').textContent=studyMinutes>=60?`${(studyMinutes/60).toFixed(1)}h`:`${studyMinutes}m`; if($('#statCode')) $('#statCode').textContent=`${state.code.projects.length}`; if($('#codeBadge')) $('#codeBadge').textContent=state.code.projects.length; if($('#sportBadge')) $('#sportBadge').textContent=state.sport.workouts.length;
  const hm=$('#codeHeatmap'); if(hm){ hm.innerHTML=''; const frag2=document.createDocumentFragment(); const act={}; [...state.sessions.map(x=>x.date), ...state.sport.workouts.map(x=>x.date)].forEach(d=>{ const k=String(d).slice(0,10); act[k]=(act[k]||0)+1; });
  for(let i=27;i>=0;i--){ const k=new Date(Date.now()-i*86400000).toISOString().slice(0,10); const n=Math.min(4,act[k]||0); const d=document.createElement('div'); d.className='hm'+(n?' l'+n:''); d.title=k+' — '+(act[k]||0); frag2.appendChild(d); } hm.appendChild(frag2); }
  updateGreeting(); renderGamification(); initDashDrag(); }
function updateGreeting(){ const el=$('#profileGreeting'); if(!el) return; const h=new Date().getHours(); const en=state.settings.language==='en'; const g=en?(h<12?'Good morning':h<18?'Good afternoon':'Good evening'):(h<12?'صبح بخیر':h<18?'عصر بخیر':'شب بخیر'); const name=state.profile?.name?.trim(); const goal=state.profile?.goal?.trim(); el.textContent=(name?name+(en?', ':'، '):'')+g+(goal?' — '+goal:''); const side=$('#sideName'); if(side) side.textContent=name||(en?'Your profile':'کاربر'); const sub=$('#sideSub'); if(sub) sub.textContent=state.profile?.role||(en?'Personal workspace':'دستیار شخصی'); const avatar=document.querySelector('.user-card > div'); if(avatar) avatar.textContent=(name||'A').slice(0,1).toUpperCase(); }
renderDash();

// Todos full
let todoView='kanban', todoCat='all';
function renderTodos(){
  const search=($('#todoSearch').value||'').toLowerCase(); const smart=$('#smartFilter')?.value||'all';
  let filtered=state.todos.filter(t=>{
    const cat=todoCat==='all'||t.cat===todoCat; const s=!search || t.text.toLowerCase().includes(search);
    let sm=true; if(smart==='today') sm=t.dueDate===new Date().toISOString().slice(0,10); if(smart==='overdue') sm=t.dueDate && new Date(t.dueDate)<new Date(new Date().toDateString()) && !t.done; if(smart==='recurring') sm=!!t.recurring; return cat && s && sm;
  });
  ['backlog','doing','done'].forEach(status=>{
    const list=$(`#kan-${status}`); if(!list) return; const frag=document.createDocumentFragment(); list.innerHTML=''; const items=filtered.filter(t=>t.status===status); const cnt=$(`#cnt-${status}`); if(cnt) cnt.textContent=items.length;
    items.forEach(t=>{
      const el=document.createElement('div'); el.className='item'; el.draggable=true; el.dataset.id=t.id;
      el.innerHTML=`<div style="display:flex; justify-content:space-between"><b style="font-size:12px">${esc(t.text)}</b><span class="chip">${esc(tr(({low:'عادی',med:'متوسط',high:'فوری'})[t.prio]||t.prio))}</span></div><div class="meta"><span class="chip">${esc(tr(({work:'کار',personal:'شخصی',study:'درس',sport:'ورزش',code:'کد'})[t.cat]||t.cat))}</span><span class="chip">${relDays(t.dueDate)}</span>${t.recurring?'<span class="chip" style="background:rgba(6,182,214,.12);color:#a5f3fc">🔁</span>':''}${t.estimate?`<span class="chip">⏱️ ${t.estimate}m</span>`:''}</div>`;
      el.addEventListener('dragstart',e=>{ e.dataTransfer.setData('text/plain', t.id); el.style.opacity='.6'; }, {passive:true});
      el.addEventListener('dragend',()=>{ el.style.opacity='1'; }, {passive:true});
      el.innerHTML+=`<div class="task-actions"><button type="button" class="btn small task-action" data-task-action="complete" aria-label="${esc(tr(t.status==='done'?'بازگردانی':'تکمیل'))}">${esc(tr(t.status==='done'?'بازگردانی':'تکمیل'))}</button><button type="button" class="btn small task-action" data-task-action="edit" aria-label="${esc(tr('ویرایش'))}">${esc(tr('ویرایش'))}</button><button type="button" class="btn small task-action danger" data-task-action="delete" aria-label="${esc(tr('حذف'))}">${esc(tr('حذف'))}</button></div>`; el.addEventListener('click',event=>{const action=event.target.closest('[data-task-action]')?.dataset.taskAction;if(!action)return;event.stopPropagation();if(action==='edit')openTodoEdit(t.id);if(action==='delete')deleteTodo(t.id);if(action==='complete')setTodoDone(t.id,t.status!=='done');}); el.addEventListener('dblclick',()=>openTodoEdit(t.id), {passive:true});
      frag.appendChild(el);
    });
    list.appendChild(frag);
  });
  const listView=$('#todoList'); if(listView){ listView.innerHTML=''; const listFrag=document.createDocumentFragment(); if(!filtered.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=tr('هنوز کاری ثبت نشده است.');listFrag.appendChild(empty);} filtered.slice().sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).forEach(t=>{const row=document.createElement('div');row.className='item task-list-row';row.innerHTML=`<div><b>${esc(t.text)}</b><div class="meta"><span class="chip">${esc(tr(({low:'عادی',med:'متوسط',high:'فوری'})[t.prio]||t.prio))}</span><span class="chip">${relDays(t.dueDate)}</span></div></div><div class="task-actions"><button class="btn small task-action" data-task-action="complete">${esc(tr(t.status==='done'?'بازگردانی':'تکمیل'))}</button><button class="btn small task-action" data-task-action="edit">${esc(tr('ویرایش'))}</button><button class="btn small task-action danger" data-task-action="delete">${esc(tr('حذف'))}</button></div>`;row.querySelector('[data-task-action="complete"]').addEventListener('click',()=>setTodoDone(t.id,t.status!=='done'));row.querySelector('[data-task-action="edit"]').addEventListener('click',()=>openTodoEdit(t.id));row.querySelector('[data-task-action="delete"]').addEventListener('click',()=>deleteTodo(t.id));listFrag.appendChild(row);});listView.appendChild(listFrag);}
  const cal=$('#todoCal'); if(cal){ cal.innerHTML=''; const frag=document.createDocumentFragment(); for(let d=1; d<=30; d++){ const cell=document.createElement('div'); cell.className='cal-day'; cell.innerHTML=`<span>${d}</span>`; frag.appendChild(cell); } cal.appendChild(frag); }
}
function initKanban(){ $$('.kan-col').forEach(col=>{ col.addEventListener('dragover',e=>{ e.preventDefault(); col.querySelector('.kan-list')?.classList.add('drag-over'); }, {passive:false}); col.addEventListener('dragleave',()=>col.querySelector('.kan-list')?.classList.remove('drag-over')); col.addEventListener('drop',e=>{ e.preventDefault(); col.querySelector('.kan-list')?.classList.remove('drag-over'); const id=e.dataTransfer.getData('text/plain'); const todo=state.todos.find(t=>t.id===id); if(todo){ const newlyDone=!todo.done&&col.dataset.status==='done'; todo.status=col.dataset.status; todo.done=col.dataset.status==='done'; if(newlyDone){ if(todo.recurring){ const nt={...structuredClone(todo), id:uid(), dueDate:new Date(Date.now()+86400000).toISOString().slice(0,10), status:'backlog', done:false}; state.todos.push(nt); } state.gamification.xp+=20; playSuccess(); launchConfetti(); haptic(30); } else playPop(600); save(); renderTodos(); renderDash(); } }); }); }
$('#todoViewTabs')?.addEventListener('click',e=>{ const t=e.target.closest('.tab'); if(!t) return; $$('#todoViewTabs .tab').forEach(x=>x.classList.remove('active')); t.classList.add('active'); const v=t.dataset.v; $('#kanbanView').style.display=v==='kanban'?'grid':'none'; $('#listView').style.display=v==='list'?'block':'none'; $('#calendarView').style.display=v==='calendar'?'block':'none'; }, {passive:true});
$('#todoCatTabs')?.addEventListener('click',e=>{ const t=e.target.closest('.tab'); if(!t) return; $$('#todoCatTabs .tab').forEach(x=>x.classList.remove('active')); t.classList.add('active'); todoCat=t.dataset.cat; requestAnimationFrame(renderTodos); }, {passive:true});
$('#todoSearch')?.addEventListener('input',()=>requestAnimationFrame(renderTodos), {passive:true});
$('#smartFilter')?.addEventListener('change',()=>requestAnimationFrame(renderTodos), {passive:true});
let editingTodo=null;
function openTodoEdit(id=null, status=null){ editingTodo=id?state.todos.find(t=>t.id===id):null; if($('#todoModalTitle')) $('#todoModalTitle').textContent=tr(editingTodo?'ویرایش کار':'کار جدید'); if($('#mSaveTodo')) $('#mSaveTodo').textContent=tr(editingTodo?'ذخیرهٔ تغییرات':'ذخیره + صدا'); if($('#mTodoTitle')) $('#mTodoTitle').value=editingTodo?.text||''; if($('#mTodoCat')) $('#mTodoCat').value=editingTodo?.cat||'personal'; if($('#mTodoPrio')) $('#mTodoPrio').value=editingTodo?.prio||'med'; if($('#mTodoStatus')) $('#mTodoStatus').value=status||editingTodo?.status||'backlog'; if($('#mTodoDue')) $('#mTodoDue').value=editingTodo?.dueDate||''; if($('#mRecurring')) $('#mRecurring').checked=editingTodo?.recurring||false; if($('#mEstimate')) $('#mEstimate').value=editingTodo?.estimate||''; openModal('todoModal'); playPop(700); }
$('#addTodo')?.addEventListener('click',()=>openTodoEdit(), {passive:true}); $('#addBtn')?.addEventListener('click',()=>openTodoEdit(), {passive:true}); $('#quickStart')?.addEventListener('click',()=>{navigate('todos'); openTodoEdit();}, {passive:true});
$('#mSaveTodo')?.addEventListener('click',()=>{ const title=$('#mTodoTitle').value.trim(); if(!title){$('#mTodoTitle').focus();return;} if(editingTodo){ Object.assign(editingTodo,{text:title, cat:$('#mTodoCat').value, prio:$('#mTodoPrio').value, status:$('#mTodoStatus').value, dueDate:$('#mTodoDue').value, recurring:$('#mRecurring')?.checked||false, estimate:parseInt($('#mEstimate').value)||0, done:$('#mTodoStatus').value==='done'}); } else { state.todos.unshift({id:uid(), text:title, cat:$('#mTodoCat').value, prio:$('#mTodoPrio').value, status:$('#mTodoStatus').value, dueDate:$('#mTodoDue').value, recurring:$('#mRecurring')?.checked||false, estimate:parseInt($('#mEstimate').value)||0, done:$('#mTodoStatus').value==='done', createdAt:new Date().toISOString()}); } save(); closeModal('todoModal'); renderTodos(); renderDash(); playSuccess(); }, {passive:true});
function setTodoDone(id,done){const todo=state.todos.find(item=>item.id===id);if(!todo)return;todo.done=done;todo.status=done?'done':'backlog';if(done){state.gamification.xp=(state.gamification.xp||0)+20;playSuccess();launchConfetti();}save();renderTodos();renderDash();renderGamification();}
function deleteTodo(id){const todo=state.todos.find(item=>item.id===id);if(!todo)return;if(!confirm(tr('این کار حذف شود؟')))return;state.todos=state.todos.filter(item=>item.id!==id);save();renderTodos();renderDash();}
initKanban(); renderTodos();

// Study
function renderStudy(){
  const sList=$('#subjectList'); if(sList){ sList.innerHTML=''; const frag=document.createDocumentFragment(); state.subjects.forEach(s=>{ const el=document.createElement('div'); el.className='item'; el.innerHTML=`<b style="font-size:12px">${esc(s.name)}</b>`; frag.appendChild(el); }); sList.appendChild(frag); }
  const grid=$('#timetableGrid'); if(grid){ grid.innerHTML=''; const frag=document.createDocumentFragment(); for(let h=8; h<16; h++){ const head=document.createElement('div'); head.className='tt-head'; head.textContent=h+':00'; frag.appendChild(head); for(let d=0; d<7; d++){ const cell=document.createElement('div'); cell.className='tt-cell'; const blocks=state.timetable.filter(b=>b.day===d && Math.floor(b.start)===h); blocks.forEach(b=>{ const sub=state.subjects.find(s=>s.id===b.subjectId); const block=document.createElement('div'); block.className='tt-block'; block.style.background=sub?.color||'#8b5cf6'; block.textContent=tr(sub?.name||'درس'); block.addEventListener('click',()=>{ state.timetable=state.timetable.filter(x=>x.id!==b.id); save(); renderStudy(); playPop(400); }, {passive:true}); cell.appendChild(block); }); frag.appendChild(cell); } } grid.appendChild(frag); }
  const sess=$('#sessionsList'); if(sess){ sess.innerHTML=''; const frag=document.createDocumentFragment(); state.sessions.forEach(s=>{ const el=document.createElement('div'); el.className='item'; el.textContent=`${s.duration} ${state.settings.language==='en'?'min':'دقیقه'} - ${new Date(s.date).toLocaleDateString(state.settings.language==='en'?'en-US':'fa-IR')}`; frag.appendChild(el); }); sess.appendChild(frag); }
  const ex=$('#examsList'); if(ex){ ex.innerHTML=''; const frag=document.createDocumentFragment(); state.exams.forEach(e=>{ const el=document.createElement('div'); el.className='item'; el.innerHTML=`<b>${esc(e.title)}</b> <span class="chip">${relDays(e.date)}</span>`; frag.appendChild(el); }); ex.appendChild(frag); }
  const flashBox=$('#flashBox'); if(flashBox){ if(state.flashcards.length){ const card=state.flashcards[0]; flashBox.innerHTML=`<div class="item"><b style="font-size:12px">${esc(card.q)}</b><div id="flashAns" style="display:none; margin-top:8px; padding:8px; background:rgba(255,255,255,.05); border-radius:8px; font-size:11px">${esc(card.a)}</div><div style="display:flex; gap:6px; margin-top:8px"><button class="btn small" id="showAns">نمایش</button><button class="btn small primary" id="nextFlash">بعدی +20 XP</button></div></div>`; $('#showAns')?.addEventListener('click',()=>{ $('#flashAns').style.display='block'; playPop(600); }, {passive:true}); $('#nextFlash')?.addEventListener('click',()=>{ state.flashcards.push(state.flashcards.shift()); state.gamification.xp+=20; save(); renderStudy(); renderGamification(); playSuccess(); haptic(18); }, {passive:true}); } else flashBox.innerHTML=`<div class="empty">${tr('فلش کارتی نیست')}</div>`; }
}
