$('#addTimetable')?.addEventListener('click',()=>{if(!state.subjects.length){alert(tr('اول یک درس اضافه کن.'));return;}const subjectList=state.subjects.map((item,index)=>`${index+1}. ${item.name}`).join('\n');const rawSubject=prompt(tr('شمارهٔ درس را انتخاب کن:')+'\n'+subjectList,'1');if(rawSubject===null)return;const subjectIndex=Number(String(rawSubject).replace(/[۰-۹]/g,d=>String(d.charCodeAt(0)-1776)))-1;if(!Number.isInteger(subjectIndex)||subjectIndex<0||subjectIndex>=state.subjects.length)return;const subject=state.subjects[subjectIndex];const rawDay=prompt(tr('روز هفته را از ۰ تا ۶ وارد کن (شنبه تا جمعه):'),'0');if(rawDay===null)return;const day=Number(String(rawDay).replace(/[۰-۹]/g,d=>String(d.charCodeAt(0)-1776)));if(!Number.isInteger(day)||day<0||day>6)return;const rawStart=prompt(tr('ساعت شروع را به شکل ۸ یا ۱۳ وارد کن:'),'9');if(rawStart===null)return;const start=Number(String(rawStart).replace(/[۰-۹]/g,d=>String(d.charCodeAt(0)-1776)));if(!Number.isFinite(start)||start<8||start>15)return;state.timetable.push({id:uid(),subjectId:subject.id,day,start,duration:1});save();renderStudy();playSuccess();});
