// Sport with photos
function renderSport(){
  const prog=$('#programsList'); if(prog){ prog.innerHTML=''; const frag=document.createDocumentFragment(); state.sport.programs.forEach(p=>{ const el=document.createElement('div'); el.className='item'; el.innerHTML=`<b style="font-size:11.5px">${esc(p.name)}</b>`; frag.appendChild(el); }); prog.appendChild(frag); }
  const sCal=$('#sportCal'); if(sCal){ sCal.innerHTML=''; const frag=document.createDocumentFragment(); for(let i=1;i<=30;i++){ const el=document.createElement('div'); el.className='cal-day'; el.innerHTML=`<span>${i}</span>`; frag.appendChild(el); } sCal.appendChild(frag); }
  const wLog=$('#weightLog'); if(wLog){ wLog.innerHTML=''; const frag=document.createDocumentFragment(); state.sport.body.forEach(b=>{ const el=document.createElement('div'); el.className='item'; el.textContent=`${b.weight}kg`; frag.appendChild(el); }); wLog.appendChild(frag); }
  if($('#sportStreak')) $('#sportStreak').textContent=state.sport.workouts.length+' روز';
  if($('#sportCal')) $('#sportCal').textContent=state.sport.workouts.length*200;
  if($('#sportWeight')) $('#sportWeight').textContent=(state.sport.body[state.sport.body.length-1]?.weight||'--')+' kg';
  if($('#sportTotal')) $('#sportTotal').textContent=state.sport.workouts.length;
  if($('#sportWeek')) $('#sportWeek').textContent=state.sport.workouts.length;
  const last=state.sport.workouts[state.sport.workouts.length-1]; let sug='Push'; if(last){ const txt=last.exercises.map(e=>e.name).join(' '); if(txt.includes('پرس')||txt.includes('سینه')) sug='Pull'; else if(txt.includes('بارفیکس')) sug='Leg'; else if(txt.includes('اسکات')) sug='Push'; } if($('#aiSuggest')) $('#aiSuggest').textContent=tr(sug)+' '+tr('پیشنهاد');
  const beforePrev=$('#beforePreview'), afterPrev=$('#afterPreview');
  if(state.sport.photos.before && beforePrev) beforePrev.innerHTML=`<img src="${esc(state.sport.photos.before)}" />`;
  if(state.sport.photos.after && afterPrev) afterPrev.innerHTML=`<img src="${esc(state.sport.photos.after)}" />`;
}
