// Code + Monaco toggle
let monacoEditor=null, monacoLoaded=false;
async function loadMonaco(){
  if(monacoLoaded) return;
  return new Promise((resolve,reject)=>{
    const s=document.createElement('script'); s.src='https://cdn.jsdelivr.net/npm/monaco-editor@0.45.0/min/vs/loader.js';
    s.onload=()=>{ require.config({paths:{vs:'https://cdn.jsdelivr.net/npm/monaco-editor@0.45.0/min/vs'}}); require(['vs/editor/editor.main'], ()=>{ monacoLoaded=true; resolve(); }); };
    s.onerror=reject; document.head.appendChild(s);
  });
}
async function initMonaco(){
  try{
    await loadMonaco();
    const cont=$('#monacoContainer'); if(!cont) return; cont.style.display='block'; const ta=$('#codeEditor'); if(ta) ta.style.display='none';
    if(!monacoEditor){ monacoEditor=monaco.editor.create(cont, {value:state.focusEditor||'// کد خود را اینجا بنویسید\n', language:'javascript', theme:'vs-dark', fontFamily:'JetBrains Mono', fontSize:12, minimap:{enabled:false}, automaticLayout:true}); monacoEditor.onDidChangeModelContent(()=>{ state.focusEditor=monacoEditor.getValue(); save(); }); }
  }catch{ alert(tr('ویرایشگر Monaco برای بارگذاری به اینترنت نیاز دارد؛ از ویرایشگر ساده استفاده کنید.')); }
}
let codeTab='projects', activeSnippet=null;
function renderCode(){
  const grid=$('#projectsGrid'); if(grid){ grid.innerHTML=''; const frag=document.createDocumentFragment(); state.code.projects.forEach(p=>{ const el=document.createElement('div'); el.className='glass-card'; el.innerHTML=`<div class="card-pad"><b style="font-size:12px">${esc(p.name)}</b><div style="font-size:11px; color:var(--muted)">${esc(p.desc)}</div><div class="progress" style="margin-top:8px"><i style="width:${p.progress}%"></i></div></div>`; frag.appendChild(el); }); grid.appendChild(frag); }
  const q=($('#snippetSearch')?.value||'').toLowerCase(); const filtered=state.code.snippets.filter(s=>!q||s.title.toLowerCase().includes(q));
  const list=$('#snippetList'); if(list){ list.innerHTML=''; const frag=document.createDocumentFragment(); filtered.forEach(s=>{ const el=document.createElement('div'); el.className='item'; el.style.padding='8px'; el.innerHTML=`<b style="font-size:11px">${esc(s.title)}</b>`; el.addEventListener('click',()=>{activeSnippet=s; $('#snippetTitle').textContent=s.title; $('#snippetCode').textContent=s.code;}, {passive:true}); frag.appendChild(el); }); list.appendChild(frag); }
  if($('#snippetCount2')) $('#snippetCount2').textContent=filtered.length;
}
$$('[data-code]').forEach(t=>t.addEventListener('click',()=>{$$('[data-code]').forEach(x=>x.classList.remove('active')); t.classList.add('active'); const v=t.dataset.code; $('#codeProjectsView').style.display=v==='projects'?'block':'none'; $('#codeSnippetsView').style.display=v==='snippets'?'block':'none'; $('#codeEditorView').style.display=v==='editor'?'block':'none'; playPop(500);}, {passive:true}));
$('#addProject')?.addEventListener('click',()=>{ const n=prompt(tr('نام:')); if(!n) return; state.code.projects.push({id:uid(), name:n, desc:'', stack:[], status:'dev', progress:10, deadline:new Date().toISOString().slice(0,10)}); save(); renderCode(); playSuccess(); }, {passive:true});
$('#addSnippet')?.addEventListener('click',()=>{ const t=prompt(tr('عنوان:')); if(!t) return; state.code.snippets.push({id:uid(), title:t, lang:'JS', code:'// code'}); save(); renderCode(); playSuccess(); }, {passive:true});
