// Notes markdown live
function parseMD(md){ md=esc(md); return md.replace(/^### (.*$)/gim,'<h3>$1</h3>').replace(/^## (.*$)/gim,'<h2>$1</h2>').replace(/^# (.*$)/gim,'<h1>$1</h1>').replace(/```([\s\S]*?)```/g,'<pre><code>$1</code></pre>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/\*([^*]+)\*/g,'<i>$1</i>').replace(/^- (.*$)/gim,'<li>$1</li>').replace(/\n/g,'<br>'); }
let curFolder='f1', editingNote=null;
function renderNotes(){
  const fList=$('#foldersList'); if(fList){ fList.innerHTML=''; const frag=document.createDocumentFragment(); state.notes.folders.forEach(f=>{ const el=document.createElement('div'); el.className='nav-item'+(curFolder===f.id?' active':''); el.innerHTML=`<span class="nav-label">${esc(f.name)}</span><span class="nav-badge">${state.notes.items.filter(n=>n.folderId===f.id).length}</span>`; el.addEventListener('click',()=>{curFolder=f.id; renderNotes(); playPop(400);}, {passive:true}); frag.appendChild(el); }); fList.appendChild(frag); }
  const grid=$('#notesGrid'); if(grid){ grid.innerHTML=''; const frag=document.createDocumentFragment(); state.notes.items.filter(n=>n.folderId===curFolder).filter(n=>{const q=($('#noteSearch')?.value||'').trim().toLowerCase();return !q||`${n.title||''} ${n.text||''}`.toLowerCase().includes(q);}).forEach(n=>{ const el=document.createElement('div'); el.className='item'; el.innerHTML=`<b style="font-size:12px">${esc(tr(n.title||'بدون عنوان'))}</b><div style="font-size:11px; color:var(--muted)">${esc(n.text.slice(0,80))}</div>`; el.addEventListener('click',()=>{editingNote=n; $('#noteTitle').value=n.title; $('#noteBody').value=n.text; $('#mdPreview').innerHTML=parseMD(n.text); playPop(500);}, {passive:true}); frag.appendChild(el); }); grid.appendChild(frag); }
}
$('#noteSearch')?.addEventListener('input',()=>requestAnimationFrame(renderNotes),{passive:true});
$('#noteBody')?.addEventListener('input',e=>{ $('#mdPreview').innerHTML=parseMD(e.target.value)||`<span style="color:var(--muted)">${tr('پیش‌نمایش...')}</span>`; }, {passive:true});
$('#addFolder')?.addEventListener('click',()=>{ const name=prompt(tr('نام پوشه:')); if(!name?.trim()) return; const folder={id:uid(),name:name.trim()};state.notes.folders.push(folder);curFolder=folder.id;save();renderNotes();playPop(600); });
$('#saveNote')?.addEventListener('click',()=>{ const t=$('#noteTitle').value.trim(), b=$('#noteBody').value.trim(); if(!b) return; if(!state.notes.folders.length){const folder={id:uid(),name:tr('یادداشت‌هایم')};state.notes.folders.push(folder);curFolder=folder.id;}if(editingNote){ editingNote.title=t; editingNote.text=b; } else state.notes.items.push({id:uid(), folderId:curFolder, title:t, text:b, createdAt:new Date().toISOString()}); $('#noteTitle').value=''; $('#noteBody').value=''; $('#mdPreview').innerHTML=`<span style="color:var(--muted)">${tr('پیش‌نمایش...')}</span>`; editingNote=null; save(); renderNotes(); playSuccess(); }, {passive:true});
renderNotes();

