// Command palette with > commands
function openCmd(query=''){ const bg=$('#cmdPalette'); if(!bg) return; bg.style.display='grid'; requestAnimationFrame(()=>bg.classList.add('open')); const inp=$('#cmdInput'); if(inp){inp.value=query;inp.focus();} renderCmd(query); playPop(600); }
function closeCmd(){ const bg=$('#cmdPalette'); if(!bg) return; bg.classList.remove('open'); setTimeout(()=>{ if(!bg.classList.contains('open')) bg.style.display='none'; }, 200); }
$('#cmdBtn')?.addEventListener('click',openCmd, {passive:true});
$('#globalSearch')?.addEventListener('keydown',e=>{ if(e.key==='Enter'){e.preventDefault();openCmd(e.target.value.trim());} if(e.key==='/' && !e.target.value){e.preventDefault();openCmd();} }, {passive:false});
document.addEventListener('keydown',e=>{ if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='k'){ e.preventDefault(); openCmd(); } if(e.key==='Escape'){ closeCmd(); $$('.modal-bg').forEach(m=>closeModal(m.id)); const z=$('#zenOverlay'); if(z?.classList.contains('active')){ z.classList.remove('active'); $('#zenContent')?.classList.remove('active'); } } }, {passive:true});
$('#cmdPalette')?.addEventListener('click',e=>{ if(e.target.id==='cmdPalette') closeCmd(); }, {passive:true});
function renderCmd(q){
  const list=$('#cmdList'); if(!list) return; list.innerHTML=''; const qq=q.toLowerCase(); let items=[];
  if(qq.startsWith('>')){
    const cmd=qq.slice(1).trim();
    const cmds=[
      {id:'zen', title:tr('حالت Zen برای صفحه فعلی'), action:()=>{ const active=document.querySelector('.view.active'); if(active) openZen(active.id.replace('view-','')); closeCmd(); }},
      {id:'confetti', title:tr('🎊 کانفتی!'), action:()=>{ launchConfetti(); playSuccess(); closeCmd(); }},
      {id:'new task', title:tr('کار جدید'), action:()=>{ openTodoEdit(); closeCmd(); }},
    ];
    items=cmds.filter(c=>!cmd || c.id.includes(cmd) || c.title.includes(cmd)).map(c=>({type:tr('دستور >'), title:c.title, action:c.action}));
  } else {
    items=[
      ...state.todos.map(t=>({type:tr('کار'), title:t.text, action:()=>{navigate('todos'); openTodoEdit(t.id); closeCmd();}})),
      ...state.notes.items.map(n=>({type:tr('یادداشت'),title:n.title||tr('بدون عنوان'),action:()=>{navigate('notes');curFolder=n.folderId;renderNotes();editingNote=n;$('#noteTitle').value=n.title||'';$('#noteBody').value=n.text||'';$('#mdPreview').innerHTML=parseMD(n.text||'');closeCmd();}})),
      ...state.subjects.map(item=>({type:tr('درس'),title:item.name,action:()=>navigate('study')})),
      ...state.code.projects.map(item=>({type:tr('پروژه'),title:item.name,action:()=>navigate('code')})),
      {type:tr('رفتن'), title:tr('داشبورد'), action:()=>{navigate('dashboard'); closeCmd();}},
      {type:tr('رفتن'), title:tr('کارها'), action:()=>{navigate('todos'); closeCmd();}},
    ].filter(i=>!qq||i.title.toLowerCase().includes(qq));
  }
  const frag=document.createDocumentFragment();
  items.slice(0,8).forEach(i=>{ const el=document.createElement('div'); el.className='item'; el.style.margin='2px 6px'; el.innerHTML=`<span class="chip">${i.type}</span> ${esc(i.title)}`; el.addEventListener('click',()=>{ playPop(600); i.action(); }, {passive:true}); frag.appendChild(el); });
  list.appendChild(frag);
}
$('#cmdInput')?.addEventListener('input',e=>renderCmd(e.target.value), {passive:true});

// Onboarding with spotlight
const onboardingSteps=[
  {title:'خوش آمدید! 👋', desc:'کارها، درس، ورزش، کد و یادداشت‌هایتان را یک‌جا مدیریت کنید: Zen، درگ، XP، عکس قبل/بعد، Monaco و مارک‌داون.', icon:'👋', target:null},
  {title:'درگ داشبورد 🌿', desc:'هر کارت شیشه‌ای رو بگیر بکش — جاش عوض میشه. با transform نرم، بدون لگ.', icon:'✋', target:'#dashBento'},
  {title:'Zen هر بخش 🎯', desc:'دکمه Zen رو بزن، همه محو میشه جز اون بخش — برای فوکوس عمیق.', icon:'◐', target:'#zenBtn'},
  {title:'گیمیفیکیشن + کانفتی 🎊', desc:'کار تموم کنی XP، عکس قبل/بعد، Monaco، مارک‌داون زنده — همه با صدای پاپ و کانفتی.', icon:'🏆', target:'#badgeGrid'},
];
let onboardIdx=0;
function showOnboarding(){ if(state.settings.onboardingDone) return; $('#onboarding').classList.add('active'); renderOnboard(); }
function renderOnboard(){
  const step=onboardingSteps[onboardIdx]; if(!step) return;
  $('#onboardTitle').textContent=tr(step.title); $('#onboardDesc').textContent=tr(step.desc); $('#onboardIcon').textContent=step.icon;
  $('#onboardDots').innerHTML=onboardingSteps.map((_,i)=>`<div style="width:${i===onboardIdx?'18px':'7px'};height:7px; border-radius:999px; background:${i===onboardIdx?'#fff':'rgba(255,255,255,.25)'}; transition:.3s"></div>`).join('');
  const spot=$('#spotlight'); if(step.target){ const target=document.querySelector(step.target); if(target){ const r=target.getBoundingClientRect(); spot.style.display='block'; spot.style.top=(r.top-8)+'px'; spot.style.left=(r.left-8)+'px'; spot.style.width=(r.width+16)+'px'; spot.style.height=(r.height+16)+'px'; } else spot.style.display='none'; } else spot.style.display='none';
}
$('#onboardNext')?.addEventListener('click',()=>{
  if(onboardIdx<onboardingSteps.length-1){ onboardIdx++; renderOnboard(); playPop(600); }
  else{ $('#onboarding').classList.remove('active'); $('#spotlight').style.display='none'; state.settings.onboardingDone=true; save(); playSuccess(); launchConfetti(); }
}, {passive:true});
$('#onboardSkip')?.addEventListener('click',()=>{ $('#onboarding').classList.remove('active'); $('#spotlight').style.display='none'; state.settings.onboardingDone=true; save(); }, {passive:true});
setTimeout(()=>{ if(!state.settings.onboardingDone) showOnboarding(); }, 900);

