$('#exportData')?.addEventListener('click',()=>{ const blob=new Blob([JSON.stringify(state)],{type:'application/json'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='dastyar-full-soft.json'; a.click(); playPop(700); }, {passive:true});
$('#importBtn')?.addEventListener('click',()=>$('#importFile').click(), {passive:true});
$('#importFile')?.addEventListener('change',e=>{ const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=()=>{ try{ const j=JSON.parse(r.result); if(!j||typeof j!=='object'||Array.isArray(j)||!Array.isArray(j.todos||[])) throw 0; state={...state, ...j}; save(); location.reload(); }catch{ alert(tr('فایل واردشده معتبر نیست.')); } }; r.readAsText(f); }, {passive:true});
$('#clearData')?.addEventListener('click',()=>{ if(confirm(tr('حذف همه؟'))){ localStorage.removeItem('dastyar_full_soft'); location.reload(); }}, {passive:true});
$('#soundToggle')?.addEventListener('click',function(){ state.settings.sound=!state.settings.sound; applySettings(); renderSettings(); const icon=this.querySelector('i'); if(icon) icon.className=state.settings.sound?'ri-volume-up-line':'ri-volume-mute-line'; const sb=$('#soundBadge'); if(sb) sb.textContent=state.settings.sound?'فعال':'خاموش'; const cb=$('#confettiBadge'); if(cb) cb.textContent=state.settings.confetti?'فعال':'خاموش'; playPop(state.settings.sound?800:400); }, {passive:true});
renderSettings();

// Sound badge init
if($('#soundBadge')) $('#soundBadge').textContent=state.settings.sound?'فعال':'خاموش';
if($('#confettiBadge')) $('#confettiBadge').textContent=state.settings.confetti?'فعال':'خاموش';


// Profile and interface language are stored with this browser's private workspace.

const originalTextNodes=new WeakMap();
function translateNode(node,language){
 let record=originalTextNodes.get(node);
 if(!record){ const current=node.nodeValue; record={original:Object.keys(uiTranslations).find(key=>uiTranslations[key]===current)||current,translated:current}; originalTextNodes.set(node,record); }
 else if(node.nodeValue!==record.translated){ const current=node.nodeValue; record.original=Object.keys(uiTranslations).find(key=>uiTranslations[key]===current)||current; }
 const original=record.original; const key=original.trim(); const leading=original.match(/^\s*/)?.[0]||''; const trailing=original.match(/\s*$/)?.[0]||''; const core=key; const translated=language==='en'?(uiTranslations[core]||core):core; const value=leading+translated+trailing;
 if(node.nodeValue!==value) node.nodeValue=value; record.translated=value;
}
function setLanguage(language){
 state.settings.language=language; save(); document.title=language==='en'?'Dastyar Plus — Personal dashboard':'دستیار پلاس — داشبورد شخصی'; const root=document.documentElement; root.lang=language; root.dir=language==='fa'?'rtl':'ltr'; document.body.classList.toggle('english-ui',language==='en');
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT); let node; while((node=walker.nextNode())) translateNode(node,language);
 document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(input=>{ if(!input.dataset.faPlaceholder) input.dataset.faPlaceholder=input.placeholder; const fa=input.dataset.faPlaceholder; input.placeholder=language==='en'?(uiTranslations[fa]||fa):fa; });
 document.querySelectorAll('[title],[aria-label]').forEach(el=>['title','aria-label'].forEach(attr=>{const value=el.getAttribute(attr); const key='data-fa-'+attr; if(value&&!el.getAttribute(key)) el.setAttribute(key,value); const fa=el.getAttribute(key); if(fa) el.setAttribute(attr,language==='en'?(uiTranslations[fa]||fa):fa);}));
 const toggle=$('#languageToggle'); if(toggle) toggle.textContent=language==='fa'?'EN':'FA'; const tourLanguage=$('#onboardLanguage'); if(tourLanguage) tourLanguage.textContent=language==='fa'?'EN':'FA'; if($('#onboarding.active')) renderOnboard(); tick(); renderDash(); updateGreeting(); renderGamification(); renderTodos(); renderStudy(); renderSport(); renderCode(); renderNotes(); renderSettings();
}
const dynamicTextObserver=new MutationObserver(records=>{ for(const record of records){ if(record.type==='characterData') translateNode(record.target,state.settings.language||'fa'); for(const added of record.addedNodes||[]){ if(added.nodeType===Node.TEXT_NODE) translateNode(added,state.settings.language||'fa'); else if(added.nodeType===Node.ELEMENT_NODE){ const walk=document.createTreeWalker(added,NodeFilter.SHOW_TEXT); let text; while((text=walk.nextNode())) translateNode(text,state.settings.language||'fa'); } } } });
dynamicTextObserver.observe(document.body,{childList:true,subtree:true,characterData:true});
const languageButton=$('#languageToggle'); languageButton?.addEventListener('click',()=>setLanguage(state.settings.language==='fa'?'en':'fa'));
$('#onboardLanguage')?.addEventListener('click',()=>setLanguage(state.settings.language==='fa'?'en':'fa'));
$('#profileNameInput').value=state.profile?.name||''; $('#profileRoleInput').value=state.profile?.role||''; $('#profileGoalInput').value=state.profile?.goal||'';
$('#saveProfile')?.addEventListener('click',()=>{ state.profile={name:$('#profileNameInput').value.trim(),role:$('#profileRoleInput').value.trim(),goal:$('#profileGoalInput').value.trim()}; save(); updateGreeting(); playSuccess(); });
setLanguage(state.settings.language||'fa');
